-- Forecast the parts mix for problem P04, every region, next 12 weeks.
-- Target: rolling 4-week attach rate per candidate part (share of jobs using it).
-- Covariates known ahead: forecast temperature, install-base units at risk.
-- Generated by bigquery/make_sql.py.

WITH weekly AS (
  SELECT
    j.week, j.region, j.jobs,
    SUM(IF(u.part_id = 'CP-120', u.uses, 0)) AS cp_120,
    SUM(IF(u.part_id = 'FLT-SW', u.uses, 0)) AS flt_sw,
    SUM(IF(u.part_id = 'DRN-KIT', u.uses, 0)) AS drn_kit,
    SUM(IF(u.part_id = 'EVAP-PAN', u.uses, 0)) AS evap_pan
  FROM trunk.jobs_weekly AS j
  LEFT JOIN trunk.part_usage_weekly AS u
    USING (week, region, problem_code)
  WHERE j.problem_code = 'P04'
  GROUP BY j.week, j.region, j.jobs
),
rolling AS (
  SELECT
    week, region,
    SAFE_DIVIDE(SUM(cp_120) OVER w, SUM(jobs) OVER w) AS cp_120,
    SAFE_DIVIDE(SUM(flt_sw) OVER w, SUM(jobs) OVER w) AS flt_sw,
    SAFE_DIVIDE(SUM(drn_kit) OVER w, SUM(jobs) OVER w) AS drn_kit,
    SAFE_DIVIDE(SUM(evap_pan) OVER w, SUM(jobs) OVER w) AS evap_pan
  FROM weekly
  WINDOW w AS (PARTITION BY region ORDER BY week ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)
),
-- History rows carry the targets; the 12 future rows carry NULL targets and
-- the covariates, which is how AI.FORECAST knows the horizon's conditions.
data AS (
  SELECT
    wx.week, wx.region,
    r.cp_120, r.flt_sw, r.drn_kit, r.evap_pan,
    wx.avg_temp_f,
    ib.units_at_risk
  FROM trunk.weather_weekly AS wx
  JOIN trunk.install_base_weekly AS ib
    ON ib.week = wx.week AND ib.region = wx.region AND ib.problem_code = 'P04'
  LEFT JOIN rolling AS r
    ON r.week = wx.week AND r.region = wx.region
)
SELECT *
FROM AI.FORECAST(
  TABLE data,
  model => 'TimesFM 3.0',
  timestamp_col => 'week',
  id_cols => ['region'],
  target_cols => ['cp_120', 'flt_sw', 'drn_kit', 'evap_pan'],
  future_covariate_cols => ['avg_temp_f', 'units_at_risk'],
  horizon => 12,
  confidence_level => 0.8       -- 80% interval: the 10th and 90th percentiles
);
